oil experiment proved atom is mostly empty space with a tiny nucleus.',\n  'Bohr (1913): Stationary states, quantized angular momentum L = nℏ, photon emission ΔE = hν.',\n  'Schrödinger (1926): Wavefunction Ψ gives probability amplitudes. |Ψ|² is probability density.',\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function AtomicModelsPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB', 'A-Level']);\n  const [mobileControlsOpen, setMobileControlsOpen] = useState(false);\n\n  const [model, setModel] = useState<AtomicModel>('thomson');\n  const [speed, setSpeed] = useState(1);\n  const [zoom, setZoom] = useState(1);\n  const [showOrbits, setShowOrbits] = useState(true);\n  const [showNucleus, setShowNucleus] = useState(true);\n  const [showElectrons, setShowElectrons] = useState(true);\n  const [showProbability, setShowProbability] = useState(true);\n  const [showEnergyLevels, setShowEnergyLevels] = useState(true);\n  const [showSpectrum, setShowSpectrum] = useState(true);\n  const [showLabels, setShowLabels] = useState(true);\n  const [showSpin, setShowSpin] = useState(false);\n  const [showFineStructure, setShowFineStructure] = useState(false);\n  const [showZeeman, setShowZeeman] = useState(false);\n  const [magneticField, setMagneticField] = useState(0);\n  const [nQuantum, setNQuantum] = useState(1);\n  const [lQuantum, setLQuantum] = useState(0);\n  const [mQuantum, setMQuantum] = useState(0);\n  const [protonCount, setProtonCount] = useState(1);\n  const [neutronCount, setNeutronCount] = useState(0);\n  const [electronCount, setElectronCount] = useState(1);\n  const [alphaEnergy, setAlphaEnergy] = useState(5);\n\n  const params: AtomicParams = {\n    model, speed, zoom, showOrbits, showNucleus, showElectrons, showProbability,\n    showEnergyLevels, showSpectrum, showLabels, showSpin, showFineStructure,\n    showZeeman, magneticField, nQuantum, lQuantum, mQuantum,\n    protonCount, neutronCount, electronCount, alphaEnergy,\n  };\n\n  const [liveStats, setLiveStats] = useState({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((stats: typeof liveStats) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveStats(stats);\n  }, []);\n\n  const applyPreset = useCallback((presetIdx: number) => {\n    const preset = ATOMIC_PRESETS[presetIdx];\n    if (!preset) return;\n    setModel(preset.model);\n    const pp = preset.params;\n    if (pp.speed !== undefined) setSpeed(pp.speed);\n    if (pp.zoom !== undefined) setZoom(pp.zoom);\n    if (pp.showOrbits !== undefined) setShowOrbits(pp.showOrbits);\n    if (pp.showNucleus !== undefined) setShowNucleus(pp.showNucleus);\n    if (pp.showElectrons !== undefined) setShowElectrons(pp.showElectrons);\n    if (pp.showProbability !== undefined) setShowProbability(pp.showProbability);\n    if (pp.showEnergyLevels !== undefined) setShowEnergyLevels(pp.showEnergyLevels);\n    if (pp.showSpectrum !== undefined) setShowSpectrum(pp.showSpectrum);\n    if (pp.showLabels !== undefined) setShowLabels(pp.showLabels);\n    if (pp.showSpin !== undefined) setShowSpin(pp.showSpin);\n    if (pp.showFineStructure !== undefined) setShowFineStructure(pp.showFineStructure);\n    if (pp.showZeeman !== undefined) setShowZeeman(pp.showZeeman);\n    if (pp.magneticField !== undefined) setMagneticField(pp.magneticField);\n    if (pp.nQuantum !== undefined) setNQuantum(pp.nQuantum);\n    if (pp.lQuantum !== undefined) setLQuantum(pp.lQuantum);\n    if (pp.mQuantum !== undefined) setMQuantum(pp.mQuantum);\n    if (pp.protonCount !== undefined) setProtonCount(pp.protonCount);\n    if (pp.neutronCount !== undefined) setNeutronCount(pp.neutronCount);\n    if (pp.electronCount !== undefined) setElectronCount(pp.electronCount);\n    if (pp.alphaEnergy !== undefined) setAlphaEnergy(pp.alphaEnergy);\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveStats({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveStats({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  }, []);\n\n  useEffect(() => {\n    if (!validQuantumNumbers(nQuantum, lQuantum, mQuantum)) {\n      const validL = possibleLValues(nQuantum);\n      if (!validL.includes(lQuantum)) { setLQuantum(validL[0]); setMQuantum(0); }\n    }\n  }, [nQuantum]);\n\n  useEffect(() => {\n    const validM = possibleMValues(lQuantum);\n    if (!validM.includes(mQuantum)) setMQuantum(validM[0]);\n  }, [lQuantum]);\n\n  const spectrum = useMemo(() => generateHydrogenSpectrum(7), []);\n  const modelLabels: Record<AtomicModel, string> = { thomson: 'Thomson (1897)', rutherford: 'Rutherford (1911)', bohr: 'Bohr (1913)', quantum: 'Quantum (1926)' };\n\n  useTopicPreset(\"simulations-atomic-models\", { \"speed\": setSpeed,\n    \"zoom\": setZoom,\n    \"protonCount\": setProtonCount,\n    \"neutronCount\": setNeutronCount,\n    \"alphaEnergy\": setAlphaEnergy,\n    \"magneticField\": setMagneticField,\n    \"nQuantum\": setNQuantum }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Atomic Physics — From Plum Pudding to Quantum Field Theory</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Atomic Models</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {Object.keys(CC).map(c => (\n                  <button key={c} onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'}`}>\n                    {c}\n                  </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Thomson → Rutherford → Bohr → Schrödinger</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">Eₙ = -13.6 Z²/n² eV</span>\n          </div>\n\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {(['thomson', 'rutherford', 'bohr', 'quantum'] as AtomicModel[]).map(m => (\n              <button key={m} onClick={() => { setModel(m); setIsRunning(false); setResetKey(k => k + 1); }}\n                className={`shrink-0 rounded-xl border px-4 py-2 text-left hover:shadow-sm transition min-w-[140px] ${model === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-200'}`}>\n                <p className=\"text-xs font-medium\">{modelLabels[m]}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {ATOMIC_PRESETS.map((preset, i) => (\n              <button key={i} onClick={() => applyPreset(i)}\n                className=\"shrink-0 rounded-xl border border-gray-200 bg-white px-3 py-2 text-left hover:border-indigo-300 hover:shadow-sm transition min-w-[200px]\">\n                <p className=\"text-xs font-medium text-indigo-700\">{preset.name}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5 leading-relaxed\">{preset.description}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <AtomicModelsCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} onModelChange={setModel} onSpeedChange={setSpeed} controls={{run:()=>{setIsRunning(true);setIsPaused(false);},pause:()=>setIsPaused(v=>!v),reset}} onTick={handleTick} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/atomic-models\" title=\"Atomic Models\"\n                  params={{ model, speed, zoom, orbits: showOrbits ? 1 : 0, nucleus: showNucleus ? 1 : 0, electrons: showElectrons ? 1 : 0, prob: showProbability ? 1 : 0, levels: showEnergyLevels ? 1 : 0, spectrum: showSpectrum ? 1 : 0, labels: showLabels ? 1 : 0, spin: showSpin ? 1 : 0, fs: showFineStructure ? 1 : 0, zeeman: showZeeman ? 1 : 0, B: magneticField, n: nQuantum, l: lQuantum, m: mQuantum, Z: protonCount, N: neutronCount, e: electronCount, alphaE: alphaEnergy }} />\n              </div>\n\n              {/* Mobile controls toggle */}\n              <div data-stage-role=\"parameters\"><button onClick={() => setMobileControlsOpen(o => !o)} className=\"lg:hidden w-full py-2.5 text-sm font-medium rounded-xl border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 transition\">\n                {mobileControlsOpen ? 'Hide controls ▲' : 'Show controls ▼'}\n              </button></div>\n\n              <div data-stage-role=\"parameters\" className={`rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4 ${mobileControlsOpen ? '' : 'hidden lg:block'}`}>\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">Display</p>\n                    <Slider label=\"Animation speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" note=\"Time evolution speed\" />\n                    <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.3} max={3} step={0.1} set={setZoom} color=\"#10b981\" note=\"Canvas zoom level\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Nucleus</p>\n                    <Slider label=\"Protons Z\" unit=\"\" value={protonCount} min={1} max={92} step={1} set={setProtonCount} color=\"#fbbf24\" note=\"Atomic number\" />\n                    <Slider label=\"Neutrons N\" unit=\"\" value={neutronCount} min={0} max={150} step={1} set={setNeutronCount} color=\"#a78bfa\" note=\"Neutron number\" />\n                  </div>\n                </div>\n\n                {model === 'rutherford' && (\n                  <div className=\"border-t border-gray-100 pt-3\">\n                    <Slider label=\"α-particle energy\" unit=\"MeV\" value={alphaEnergy} min={1} max={10} step={0.5} set={setAlphaEnergy} color=\"#f43f5e\" note=\"Kinetic energy of incoming α particles\" />\n                  </div>\n                )}\n\n                {model === 'bohr' && (\n                  <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                    <p className=\"text-[10px] font-medium text-emerald-600 uppercase tracking-wide\">Bohr Model Options</p>\n                    <div className=\"flex flex-wrap gap-3\">\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showOrbits} onChange={e => setShowOrbits(e.target.checked)} className=\"rounded\" /> Show orbits</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showEnergyLevels} onChange={e => setShowEnergyLevels(e.target.checked)} className=\"rounded\" /> Energy levels</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showSpectrum} onChange={e => setShowSpectrum(e.target.checked)} className=\"rounded\" /> Spectrum bar</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showSpin} onChange={e => setShowSpin(e.target.checked)} className=\"rounded\" /> Show spin (↑)</label>\n                    </div>\n                    <div className=\"flex flex-wrap gap-3\">\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showFineStructure} onChange={e => setShowFineStructure(e.target.checked)} className=\"rounded\" /> Fine structure (j = l ± ½)</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showZeeman} onChange={e => setShowZeeman(e.target.checked)} className=\"rounded\" /> Zeeman effect</label>\n                    </div>\n                    {showZeeman && <Slider label=\"Magnetic field B\" unit=\"T\" value={magneticField} min={0} max={5} step={0.1} set={setMagneticField} color=\"#8b5cf6\" note=\"Tesla — splits degenerate levels\" />}\n                  </div>\n                )}\n\n                {model === 'quantum' && (\n                  <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                    <p className=\"text-[10px] font-medium text-purple-600 uppercase tracking-wide\">Quantum Numbers</p>\n                    <div className=\"grid grid-cols-3 gap-3\">\n                      <Slider label=\"n\" unit=\"\" value={nQuantum} min={1} max={4} step={1} set={setNQuantum} color=\"#6366f1\" note=\"Principal quantum number\" />\n                      <Slider label=\"l\" unit=\"\" value={lQuantum} min={0} max={nQuantum - 1} step={1} set={setLQuantum} color=\"#ec4899\" note=\"Angular momentum (0=s,1=p,2=d,3=f)\" />\n                      <Slider label=\"m\" unit=\"\" value={mQuantum} min={-lQuantum} max={lQuantum} step={1} set={setMQuantum} color=\"#10b981\" note=\"Magnetic quantum number\" />\n                    </div>\n                    <p className=\"text-[10px] text-gray-400\">Orbital: <span className=\"font-medium text-indigo-600\">{nQuantum}{['s','p','d','f'][lQuantum] || '?'}</span> — <span className=\"text-gray-500\">{lQuantum === 0 ? 'spherical, no angular nodes' : lQuantum === 1 ? 'dumbbell, 1 angular node' : lQuantum === 2 ? 'cloverleaf, 2 angular nodes' : lQuantum === 3 ? 'complex 8-lobed, 3 angular nodes' : 'higher orbital'}</span></p>\n                  </div>\n                )}\n\n                <div className=\"border-t border-gray-100 pt-3\">\n                  <p className=\"text-[10px] font-medium text-gray-500 uppercase tracking-wide mb-2\">Visibility</p>\n                  <div className=\"flex flex-wrap gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showNucleus} onChange={e => setShowNucleus(e.target.checked)} className=\"rounded\" /> Nucleus</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" /> Electrons</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showProbability} onChange={e => setShowProbability(e.target.checked)} className=\"rounded\" /> Probability cloud</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showLabels} onChange={e => setShowLabels(e.target.checked)} className=\"rounded\" /> Info labels</label>\n                  </div>\n                </div>\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {model === 'bohr' && (\n                    <>\n                      <StatRow label=\"Energy Eₙ\" value={liveStats.energy.toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                      <StatRow label=\"Radius rₙ\" value={liveStats.radius.toFixed(2)} unit=\"a₀\" color=\"text-rose-500\" />\n                      <StatRow label=\"Velocity vₙ\" value={liveStats.velocity.toFixed(4)} unit=\"c·α\" color=\"text-emerald-600\" />\n                      <StatRow label=\"Quantum n\" value={liveStats.n.toString()} unit=\"\" color=\"text-blue-500\" />\n                      {liveStats.wavelength > 0 && <StatRow label=\"λ (transition)\" value={liveStats.wavelength.toFixed(1)} unit=\"nm\" color=\"text-amber-600\" />}\n                      {showFineStructure && <StatRow label=\"Fine split\" value=\"~10⁻⁴\" unit=\"eV\" color=\"text-purple-600\" />}\n                      {showZeeman && magneticField > 0 && <StatRow label=\"Zeeman ΔE\" value={(magneticField * 5.788e-5 * 1e6).toFixed(2)} unit=\"μeV\" color=\"text-pink-500\" />}\n                    </>\n                  )}\n                  {model === 'quantum' && (\n                    <>\n                      <StatRow label=\"Energy Eₙ\" value={bohrEnergy(nQuantum, protonCount).toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                      <StatRow label=\"Bohr radius\" value={bohrRadius(nQuantum, protonCount).toFixed(2)} unit=\"a₀\" color=\"text-rose-500\" />\n                      <StatRow label=\"Degeneracy\" value={(nQuantum * nQuantum).toString()} unit=\"states\" color=\"text-purple-600\" />\n                      <StatRow label=\"Orbital\" value={`${nQuantum}${['s','p','d','f'][lQuantum] || '?'}`} unit=\"\" color=\"text-emerald-600\" />\n                      <StatRow label=\"Angular nodes\" value={lQuantum.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Radial nodes\" value={(nQuantum - lQuantum - 1).toString()} unit=\"\" color=\"text-blue-500\" />\n                    </>\n                  )}\n                  {model === 'thomson' && (\n                    <>\n                      <StatRow label=\"Electrons\" value={electronCount.toString()} unit=\"\" color=\"text-blue-500\" />\n                      <StatRow label=\"Protons\" value={protonCount.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Net charge\" value=\"0\" unit=\"e\" color=\"text-emerald-600\" />\n                    </>\n                  )}\n                  {model === 'rutherford' && (\n                    <>\n                      <StatRow label=\"Nucleus Z\" value={protonCount.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Mass number A\" value={(protonCount + neutronCount).toString()} unit=\"\" color=\"text-rose-500\" />\n                      <StatRow label=\"α energy\" value={alphaEnergy.toFixed(1)} unit=\"MeV\" color=\"text-rose-500\" />\n                      <StatRow label=\"Nuclear radius\" value={(1.2 * Math.pow(protonCount + neutronCount, 1/3)).toFixed(2)} unit=\"fm\" color=\"text-purple-600\" />\n                    </>\n                  )}\n                </div>\n              </div>\n\n              {model === 'bohr' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Hydrogen Spectrum</p>\n                  <div className=\"space-y-1\">\n                    {spectrum.slice(0, 10).map((line, i) => (\n                      <div key={i} className=\"flex items-center gap-2 text-[10px]\">\n                        <div className=\"w-3 h-3 rounded-full shrink-0\" style={{ backgroundColor: line.color }} />\n                        <span className=\"text-gray-500 w-16\">{line.series}</span>\n                        <span className=\"font-mono text-gray-700\">{line.wavelength.toFixed(0)} nm</span>\n                        <span className=\"text-gray-400\">({line.fromN}→{line.toN})</span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n              )}\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {Object.keys(CC).map(c => <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'}`}>{c}</span>)}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\"><span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}</li>\n                  ))}\n                </ul>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/embed/atomic-models/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { AtomicModelsCanvas } from '@/components/simulation/AtomicModelsCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { AtomicParams, AtomicModel } from '@/lib/physics/atomicModels';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key); return v !== null ? v === '1' : fallback;\n}\nfunction str<T extends string>(sp: URLSearchParams, key: string, fallback: T, allowed: T[]): T {\n  const v = sp.get(key) as T | null;\n  return v && allowed.includes(v) ? v : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction AtomicModelsEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [model, setModel] = useState<AtomicModel>(() => str(sp, 'model', 'thomson', ['thomson', 'rutherford', 'bohr', 'quantum']));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [zoom, setZoom] = useState(() => num(sp, 'zoom', 1, 0.3, 3));\n  const [showOrbits, setShowOrbits] = useState(() => bool(sp, 'orbits', true));\n  const [showNucleus, setShowNucleus] = useState(() => bool(sp, 'nucleus', true));\n  const [showElectrons, setShowElectrons] = useState(() => bool(sp, 'electrons', true));\n  const [showProbability, setShowProbability] = useState(() => bool(sp, 'prob', true));\n  const [showEnergyLevels, setShowEnergyLevels] = useState(() => bool(sp, 'levels', true));\n  const [showSpectrum, setShowSpectrum] = useState(() => bool(sp, 'spectrum', true));\n  const [showLabels, setShowLabels] = useState(() => bool(sp, 'labels', true));\n  const [showSpin, setShowSpin] = useState(() => bool(sp, 'spin', false));\n  const [showFineStructure, setShowFineStructure] = useState(() => bool(sp, 'fs', false));\n  const [showZeeman, setShowZeeman] = useState(() => bool(sp, 'zeeman', false));\n  const [magneticField, setMagneticField] = useState(() => num(sp, 'B', 0, 0, 5));\n  const [nQuantum, setNQuantum] = useState(() => num(sp, 'n', 1, 1, 4));\n  const [lQuantum, setLQuantum] = useState(() => num(sp, 'l', 0, 0, 3));\n  const [mQuantum, setMQuantum] = useState(() => num(sp, 'm', 0, -3, 3));\n  const [protonCount, setProtonCount] = useState(() => num(sp, 'Z', 1, 1, 92));\n  const [alphaEnergy, setAlphaEnergy] = useState(() => num(sp, 'alphaE', 5, 1, 10));\n\n  const params: AtomicParams = {\n    model, speed, zoom, showOrbits, showNucleus, showElectrons, showProbability,\n    showEnergyLevels, showSpectrum, showLabels, showSpin, showFineStructure, showZeeman,\n    magneticField, nQuantum, lQuantum, mQuantum, protonCount, neutronCount: 0,\n    electronCount: 1, alphaEnergy,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"parameters\" className=\"flex gap-1 overflow-x-auto pb-1\">\n        {(['thomson', 'rutherford', 'bohr', 'quantum'] as AtomicModel[]).map(m => {\n          const labels: Record<AtomicModel, string> = { thomson: 'Thomson', rutherford: 'Rutherford', bohr: 'Bohr', quantum: 'Quantum' };\n          return (\n            <button key={m} onClick={() => { setModel(m); setIsRunning(false); setResetKey(k => k + 1); }}\n              className={`shrink-0 rounded-lg border px-3 py-1.5 text-xs font-medium transition ${model === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'}`}>\n              {labels[m]}\n            </button>\n          );\n        })}\n      </div>\n\n      <div data-stage-role=\"canvas\"><AtomicModelsCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} interactive={showControls} onModelChange={showControls?setModel:undefined} onSpeedChange={showControls?setSpeed:undefined} controls={showControls?{run:()=>{setIsRunning(true);setIsPaused(false);},pause:()=>setIsPaused(v=>!v),reset:()=>{setIsRunning(false);setIsPaused(false);setResetKey(v=>v+1);}}:undefined} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.3} max={3} step={0.1} set={setZoom} color=\"#10b981\" />\n          <Slider label=\"Protons Z\" unit=\"\" value={protonCount} min={1} max={92} step={1} set={setProtonCount} color=\"#fbbf24\" />\n          {model === 'rutherford' && <Slider label=\"α energy\" unit=\"MeV\" value={alphaEnergy} min={1} max={10} step={0.5} set={setAlphaEnergy} color=\"#f43f5e\" />}\n          {model === 'bohr' && showZeeman && <Slider label=\"B field\" unit=\"T\" value={magneticField} min={0} max={5} step={0.1} set={setMagneticField} color=\"#8b5cf6\" />}\n          {model === 'quantum' && (\n            <>\n              <Slider label=\"n\" unit=\"\" value={nQuantum} min={1} max={4} step={1} set={setNQuantum} color=\"#6366f1\" />\n              <Slider label=\"l\" unit=\"\" value={lQuantum} min={0} max={nQuantum - 1} step={1} set={setLQuantum} color=\"#ec4899\" />\n              <Slider label=\"m\" unit=\"\" value={mQuantum} min={-lQuantum} max={lQuantum} step={1} set={setMQuantum} color=\"#10b981\" />\n            </>\n          )}\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showNucleus} onChange={e => setShowNucleus(e.target.checked)} className=\"rounded\" />Nucleus</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" />Electrons</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showProbability} onChange={e => setShowProbability(e.target.checked)} className=\"rounded\" />Probability</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showLabels} onChange={e => setShowLabels(e.target.checked)} className=\"rounded\" />Labels</label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><p className=\"text-center text-[10px] text-gray-400\">Powered by <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">A-Factor STEM Studio</a></p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function AtomicModelsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <AtomicModelsEmbedInner />\n    </Suspense>\n  );\n}\n", "checks/atomic-models-layout.cjs": "const fs=require('fs'),vm=require('vm'),path=require('path'),ts=require('typescript'),React=require('react'),{renderToStaticMarkup}=require('react-dom/server'),assert=require('node:assert/strict');\nfunction load(file){file=path.resolve(file);const m={exports:{}};const req=id=>{if(id.endsWith('.css'))return{};if(id.startsWith('@/'))return load('src/'+id.slice(2)+'.ts');if(id.startsWith('.')){const target=path.resolve(path.dirname(file),id);return load(fs.existsSync(target+'.tsx')?target+'.tsx':target+'.ts');}return require(id);};vm.runInNewContext(ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText,{module:m,exports:m.exports,require:req,performance,console});return m.exports;}\nconst l=load('src/lib/physics/bohrLesson.ts'),physics=load('src/lib/physics/atomicModels.ts');\nlet s=l.startLesson(true);s=l.advanceLesson(s,1.7);assert.equal(s.phase,'incoming');assert.equal(l.occupiedLevel(s,1,2),1,'no excitation before photon arrival');s=l.advanceLesson(s,.11);assert.equal(s.phase,'excited');assert.equal(l.occupiedLevel(s,1,2),2);s=l.advanceLesson(s,2.3);assert.equal(s.phase,'emitting');assert.equal(l.occupiedLevel(s,1,2),1,'energy decreases at photon creation');s=l.advanceLesson(s,2.1);assert.equal(s.phase,'complete');assert.equal(l.advanceLesson(s,100),s);\ns=l.startLesson(false);s=l.advanceLesson(s,2);assert.equal(s.phase,'excited');assert.equal(l.advanceLesson(s,100),s,'manual absorption holds the excited atom until relaxation is chosen');s=l.nextLesson(s);assert.equal(s.phase,'emitting');\ns=l.startLesson(true,false);s=l.advanceLesson(s,2);assert.equal(s.phase,'missed');assert.equal(l.occupiedLevel(s,1,2),1);s=l.advanceLesson(s,2);assert.equal(s.phase,'ready');\nfor(let Z of [1,2,26,92])for(let a=1;a<7;a++)for(let b=a+1;b<=7;b++){const resonant=l.lessonPhoton(a,b,Z),off=l.lessonPhoton(a,b,Z,false);assert.equal(resonant.gap,physics.bohrEnergy(b,Z)-physics.bohrEnergy(a,Z));assert(resonant.energy>0);assert(off.energy>resonant.energy);assert(off.energy<physics.bohrEnergy(b+1,Z)-physics.bohrEnergy(a,Z));assert(off.energy< -physics.bohrEnergy(a,Z));for(const h of [60,100,200,500]){const labels=l.spacedEnergyLabels(a,b,Z,h);assert(labels[1].labelY-labels[0].labelY>=18);assert(labels[0].labelY>=0&&labels[1].labelY<=h);assert(l.energyY(b,Z,h)<l.energyY(a,Z,h));}}\nassert(Math.abs(l.lessonPhoton(2,3,1).wavelength-656.3)<1);\nconst base={model:'bohr',speed:1,zoom:1,showLabels:true,showOrbits:true,showNucleus:true,showElectrons:true,showEnergyLevels:true,showSpectrum:true,showSpin:false,showFineStructure:false,showZeeman:false,showProbability:true,magneticField:0,nQuantum:1,lQuantum:0,mQuantum:0,protonCount:1,neutronCount:0,electronCount:1,alphaEnergy:5};\nconst {AtomicModelsCanvas}=load('src/components/simulation/AtomicModelsCanvas.tsx');for(const model of ['bohr','thomson','rutherford','quantum']){const html=renderToStaticMarkup(React.createElement(AtomicModelsCanvas,{params:{...base,model},isRunning:false,isPaused:false}));assert(html.includes('role=\"img\"'));if(model==='bohr'){assert(html.includes('Send photon'));assert(html.includes('Let atom relax'));assert(html.includes('Next stage'));assert(html.includes('not a path through space'));assert(html.includes('Transition pair'));}if(model==='thomson'){assert(html.includes('plum-pudding'));assert(html.includes('not separate protons'));}}\nconst canvas=fs.readFileSync('src/components/simulation/AtomicModelsCanvas.tsx','utf8'),css=fs.readFileSync('src/components/simulation/atomic-models.css','utf8');assert(canvas.includes('[drawLoop, resize, params.model]'),'switching back from Bohr restarts the canvas');assert(!canvas.includes('drawBohr'),'old radial jump/radiation animation removed');assert(css.includes('.af-stage-parameters { display:none !important; }'));assert(css.includes('.af-stage-main { flex:1 1 0; overflow:hidden;'));\nconsole.log('PASS: photon-arrival causality, excitation hold, relaxation energy loss, off-resonance rejection, energy and wavelength calculations, level-label separation, four model renders, and canvas restart after switching models.');\n", "src/components/simulation/BohrRadiationLab.tsx": "'use client';\nimport {useEffect,useId,useRef,useState} from 'react';\nimport {bohrEnergy,bohrRadius,bohrVelocity,type AtomicParams} from '@/lib/physics/atomicModels';\nimport {advanceLesson,energyY,initialLesson,lessonPhoton,nextLesson,occupiedLevel,phaseDuration,spacedEnergyLabels,startLesson,type LessonState} from '@/lib/physics/bohrLesson';\ntype Stats={energy:number;radius:number;velocity:number;n:number;wavelength:number;shellConfig:string};\ntype Props={params:AtomicParams;interactive?:boolean;onTick?:(stats:Stats)=>void};\nconst phases=['ready','incoming','excited','emitting','complete'];\nconst titles:Record<string,string>={ready:'1 · Atom in its lower state',incoming:'2 · Incoming photon',excited:'3 · Absorbed → excited atom',emitting:'4 · Relaxation → emitted photon',complete:'5 · Lower state restored',missed:'Photon not absorbed'};\nfunction Packet({x,y,angle,color}:{x:number;y:number;angle:number;color:string}){return <g transform={`translate(${x} ${y}) rotate(${angle})`}><path d={Array.from({length:49},(_,i)=>`${i?'L':'M'}${i-24} ${Math.sin(i*Math.PI/8)*8*Math.sin(i/48*Math.PI)}`).join(' ')} fill=\"none\" stroke={color} strokeWidth=\"4\" strokeLinecap=\"round\"/><path d=\"M25 -5L34 0L25 5\" fill=\"none\" stroke={color} strokeWidth=\"2.5\"/></g>;}\nexport function BohrRadiationLab({params:p,onTick,interactive=true}:Props){\n const [lower,setLower]=useState(1),[upper,setUpper]=useState(2),[matched,setMatched]=useState(true),[state,setState]=useState<LessonState>(initialLesson),[playing,setPlaying]=useState(false);\n const [mobilePanel,setMobilePanel]=useState<'atom'|'energy'>('atom');\n const uid=useId().replace(/:/g,''),pairId=uid+'pair',photonId=uid+'photon';\n const onTickRef=useRef(onTick);onTickRef.current=onTick;\n const energyBox=useRef<HTMLDivElement>(null);const [energyHeight,setEnergyHeight]=useState(260);\n const Z=p.protonCount||1,photon=lessonPhoton(lower,upper,Z,matched),n=occupiedLevel(state,lower,upper),progress=Math.min(1,state.age/phaseDuration[state.phase]);\n useEffect(()=>{setState(initialLesson());setPlaying(false);},[lower,upper,Z]);\n useEffect(()=>{if(!p.showElectrons)setPlaying(false);},[p.showElectrons]);\n useEffect(()=>{const el=energyBox.current;if(!el)return;const observer=new ResizeObserver(()=>setEnergyHeight(Math.max(60,el.getBoundingClientRect().height)));observer.observe(el);return()=>observer.disconnect();},[p.showEnergyLevels]);\n useEffect(()=>{if(!playing||p.speed<=0)return;let frame=0,last:number|null=null;const tick=(now:number)=>{const dt=last===null?0:Math.min(.05,(now-last)/1000)*p.speed;last=now;setState(old=>advanceLesson(old,dt));frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);return()=>cancelAnimationFrame(frame);},[playing,p.speed]);\n useEffect(()=>{if(state.phase==='complete'||state.phase==='ready'||(state.phase==='excited'&&!state.cycle))setPlaying(false);},[state.phase,state.cycle]);\n useEffect(()=>{onTickRef.current?.({n,energy:bohrEnergy(n,Z),radius:bohrRadius(n,Z),velocity:bohrVelocity(n,Z)/2.998e8,wavelength:['incoming','emitting'].includes(state.phase)?photon.wavelength:0,shellConfig:''});},[n,Z,state.phase,photon.wavelength]);\n function begin(cycle:boolean){setState(startLesson(cycle,matched));setPlaying(true);}\n function step(){setPlaying(false);setState(old=>old.phase==='ready'||old.phase==='complete'?startLesson(false,matched):nextLesson(old));}\n const incoming=state.phase==='incoming',excited=state.phase==='excited',emitting=state.phase==='emitting',missed=state.phase==='missed';\n const electronX=excited?130:210;\n const levelRows=spacedEnergyLabels(lower,upper,Z,energyHeight);\n const text= incoming?'The atom remains in its lower state while the photon approaches.':excited?`The photon has disappeared: its energy raised the atom from n = ${lower} to n = ${upper}.`:emitting?`The electron is back at n = ${lower}. The energy difference leaves as one photon, travelling away from the atom.`:missed?'The photon energy does not match this or another bound-state gap in this idealised example. It passes without excitation.':state.phase==='complete'?'The outgoing photon carries the energy previously stored in the excited atom. Play again or choose another pair of states.':`Begin with an atom at n = ${lower}. A matching photon supplies the exact energy needed for excitation.`;\n const lightColor=matched?'#c2410c':'#64748b';\n return <section className=\"af-bohr-lesson\" aria-label=\"Photon absorption, excitation and relaxation\">\n  {interactive&&<header className=\"af-bohr-controls\">\n   <label className=\"af-bohr-pair\" htmlFor={pairId}>States<select id={pairId} aria-label=\"Transition pair\" value={`${lower}-${upper}`} onChange={e=>{const [a,b]=e.target.value.split('-').map(Number);setLower(a);setUpper(b);}}>{[1,2,3,4,5,6].flatMap(a=>[2,3,4,5,6,7].filter(b=>b>a).map(b=><option key={`${a}-${b}`} value={`${a}-${b}`}>n={a} ↔ n={b}</option>))}</select></label>\n   <label className=\"af-bohr-photon-choice\" htmlFor={photonId}>Photon<select id={photonId} value={matched?'matched':'detuned'} disabled={playing||excited} onChange={e=>{setMatched(e.target.value==='matched');setState(initialLesson());}}><option value=\"matched\">Matching energy</option><option value=\"detuned\">Off-resonance</option></select></label>\n   <div className=\"af-bohr-actions\"><button type=\"button\" onClick={()=>begin(true)} disabled={playing||excited||!p.showElectrons} aria-label=\"Play full absorption and emission cycle\">▶ Cycle</button><button type=\"button\" onClick={()=>begin(false)} disabled={playing||excited||!p.showElectrons}>Send photon</button><button type=\"button\" disabled={!excited||playing||!p.showElectrons} onClick={()=>{setState(old=>({...old,phase:'emitting',age:0}));setPlaying(true);}} aria-label=\"Let atom relax\">Relax</button><button type=\"button\" disabled={!p.showElectrons||['ready','complete'].includes(state.phase)||(excited&&!state.cycle)} onClick={()=>setPlaying(v=>!v)}>{playing?'Pause':'Resume'}</button><button type=\"button\" disabled={!p.showElectrons} onClick={step} aria-label=\"Next stage\">Step</button><button type=\"button\" onClick={()=>{setState(initialLesson());setPlaying(false);}}>Reset</button></div>\n  </header>}\n  <div className=\"af-bohr-metrics\"><span>ΔE <strong>{photon.gap.toFixed(3)} eV</strong></span><span>Photon <strong>{photon.energy.toFixed(3)} eV</strong></span><span>λ <strong>{photon.wavelength.toFixed(1)} nm · {photon.region}</strong></span><span>State <strong>n = {n}{n===1?' · ground':' · excited'}</strong></span></div>\n  <ol className=\"af-bohr-story\" aria-label=\"Radiation sequence\">{['Lower state','Photon arrives','Excited atom','Photon emitted','Lower state'].map((label,i)=><li key={i} data-active={phases.indexOf(state.phase)===i}><span>{i+1}</span>{label}</li>)}</ol>\n  {p.showEnergyLevels&&<nav className=\"af-bohr-mobile-tabs\" aria-label=\"Diagram view\"><button type=\"button\" aria-pressed={mobilePanel==='atom'} onClick={()=>setMobilePanel('atom')}>Atom</button><button type=\"button\" aria-pressed={mobilePanel==='energy'} onClick={()=>setMobilePanel('energy')}>Energy states</button></nav>}\n  <div className=\"af-bohr-diagrams\" data-mobile-panel={mobilePanel} data-levels={p.showEnergyLevels}>\n   <figure className=\"af-bohr-atom\"><figcaption>Atom in real space <small>Lower n={lower} · Upper n={upper} · amber nucleus</small></figcaption><svg viewBox=\"0 0 600 440\" role=\"img\" aria-label={`Electron in state n=${n}. ${titles[state.phase]}`}>\n    <defs><radialGradient id={uid+'bg'}><stop offset=\"0\" stopColor=\"#fff\"/><stop offset=\"1\" stopColor=\"#eff6ff\"/></radialGradient></defs>\n    <ellipse cx=\"300\" cy=\"220\" rx=\"205\" ry=\"202\" fill={`url(#${uid}bg)`}/>\n    {p.showOrbits&&<><circle cx=\"300\" cy=\"220\" r=\"90\" fill=\"none\" stroke={n===lower?'#2563eb':'#a5b4c8'} strokeWidth={n===lower?3:1.8}/><circle cx=\"300\" cy=\"220\" r=\"170\" fill=\"none\" stroke={excited?'#7c3aed':'#a5b4c8'} strokeWidth={excited?3:1.8}/></>}\n    {p.showNucleus&&<g><circle cx=\"300\" cy=\"220\" r=\"16\" fill=\"#f59e0b\" stroke=\"#92400e\" strokeWidth=\"2\"/><text x=\"300\" y=\"227\" textAnchor=\"middle\" fill=\"#78350f\" fontSize=\"24\" fontWeight=\"700\" className=\"af-bohr-nuclear-sign\">+</text></g>}\n    {p.showLabels&&<><text x=\"400\" y=\"151\" fill=\"#1e40af\" fontSize=\"21\" fontWeight=\"600\">n = {lower}</text><text x=\"449\" y=\"90\" fill=\"#6d28d9\" fontSize=\"21\" fontWeight=\"600\">n = {upper}</text><text x=\"300\" y=\"260\" textAnchor=\"middle\" fill=\"#92400e\" fontSize=\"18\">Nucleus · Z = {Z}</text></>}\n    {p.showElectrons&&<g transform={`translate(${electronX} 220)`}><circle r=\"14\" fill={excited?'#7c3aed':'#2563eb'} stroke=\"#fff\" strokeWidth=\"3\"/><path d=\"M-6 0H6\" stroke=\"#fff\" strokeWidth=\"2.5\"/>{p.showSpin&&<text x=\"0\" y=\"-21\" fill=\"#be123c\" fontSize=\"24\">↑</text>}</g>}\n    {incoming&&<Packet x={30+180*progress} y={220} angle={0} color={lightColor}/>}\n    {missed&&<Packet x={210+330*progress} y={220} angle={0} color=\"#64748b\"/>}\n    {emitting&&<Packet x={130+395*progress} y={220-150*progress} angle={-21} color=\"#7c3aed\"/>}\n    {(incoming||missed)&&<text x=\"105\" y=\"178\" fill={lightColor} textAnchor=\"middle\" fontSize=\"19\" fontWeight=\"600\">Incoming photon</text>}\n    {emitting&&<text x=\"420\" y=\"35\" fill=\"#6d28d9\" textAnchor=\"middle\" fontSize=\"19\" fontWeight=\"600\">Outgoing photon</text>}\n    {excited&&<g><circle cx=\"130\" cy=\"220\" r=\"23\" fill=\"none\" stroke=\"#7c3aed\" strokeWidth=\"2\"/><text x=\"300\" y=\"423\" textAnchor=\"middle\" fill=\"#6d28d9\" fontSize=\"20\" fontWeight=\"600\">Energy stored in the excited atom</text></g>}\n   </svg></figure>\n   {p.showEnergyLevels&&<figure className=\"af-bohr-energy\"><figcaption>Energy states <small>Selected levels · energy ↑</small></figcaption><div ref={energyBox} className=\"af-bohr-energy-plot\">\n    <svg width=\"100%\" height=\"100%\" aria-hidden=\"true\"><defs><marker id={uid+'arrow'} markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3L0 6\" fill={emitting?'#7c3aed':'#c2410c'}/></marker></defs><line x1=\"12%\" x2=\"68%\" y1=\"8\" y2=\"8\" stroke=\"#cbd5e1\" strokeDasharray=\"4 4\"/>\n    {levelRows.map(row=><g key={row.n}><line x1=\"12%\" x2=\"58%\" y1={row.y} y2={row.y} stroke={n===row.n?'#2563eb':'#94a3b8'} strokeWidth={n===row.n?3:1.5}/><line x1=\"58%\" x2=\"64%\" y1={row.y} y2={row.labelY} stroke=\"#94a3b8\"/></g>)}\n    {(excited||emitting)&&<line x1={excited?'30%':'47%'} x2={excited?'30%':'47%'} y1={energyY(excited?lower:upper,Z,energyHeight)} y2={energyY(excited?upper:lower,Z,energyHeight)} stroke={excited?'#c2410c':'#7c3aed'} strokeWidth=\"3\" markerEnd={`url(#${uid}arrow)`}/>}\n    <circle cx=\"20%\" cy={energyY(n,Z,energyHeight)} r=\"5\" fill=\"#2563eb\"/>\n    </svg>\n    {energyHeight>150&&<span className=\"af-bohr-zero\">0 eV · free electron</span>}\n    {levelRows.map(row=><span className=\"af-bohr-energy-label\" key={row.n} style={{top:row.labelY}}><strong>n = {row.n}</strong>{bohrEnergy(row.n,Z).toFixed(3)} eV</span>)}\n   </div><p>Arrow = energy change,<br/>not a path through space.</p></figure>}\n  </div>\n  <footer className=\"af-bohr-narration\" data-phase={state.phase}><strong aria-live=\"polite\">{titles[state.phase]}</strong><p>{text}</p><small>{p.showElectrons?'Distances, wave shape and timing are illustrative; sublevels, fine structure and Zeeman splitting are not modelled.':'Enable electrons to run the lesson.'}</small></footer>\n </section>;\n}\n", "src/lib/physics/bohrLesson.ts": "import {bohrEnergy,transitionWavelength} from './atomicModels';\nexport type LessonPhase='ready'|'incoming'|'excited'|'emitting'|'complete'|'missed';\nexport type LessonState={phase:LessonPhase;age:number;cycle:boolean;matched:boolean};\nexport const initialLesson=():LessonState=>({phase:'ready',age:0,cycle:false,matched:true});\nexport const phaseDuration={incoming:1.8,excited:2.2,emitting:2,missed:1.2,complete:1,ready:1};\nexport function occupiedLevel(state:LessonState,lower:number,upper:number){return state.phase==='excited'?upper:lower;}\nexport function startLesson(cycle:boolean,matched=true):LessonState{return{phase:'incoming',age:0,cycle,matched};}\nexport function nextLesson(state:LessonState):LessonState{\n const phase:LessonPhase=state.phase==='incoming'?(state.matched?'excited':'missed'):state.phase==='excited'?'emitting':state.phase==='emitting'?'complete':state.phase==='missed'?'ready':state.phase==='complete'?'ready':'incoming';\n return{...state,phase,age:0};\n}\nexport function advanceLesson(state:LessonState,dt:number):LessonState{\n if(!Number.isFinite(dt)||dt<=0||['ready','complete'].includes(state.phase)||(state.phase==='excited'&&!state.cycle))return state;\n const age=state.age+dt;return age>=phaseDuration[state.phase]?nextLesson(state):{...state,age};\n}\nexport function lessonPhoton(lower:number,upper:number,Z:number,matched=true){\n const gap=bohrEnergy(upper,Z)-bohrEnergy(lower,Z);\n // Off-resonance lies strictly between adjacent upper levels, below ionisation.\n const energy=matched?gap:(gap+bohrEnergy(upper+1,Z)-bohrEnergy(lower,Z))/2;\n return{gap,energy,wavelength:matched?transitionWavelength(upper,lower,Z):1240/energy,region:1240/energy<380?'ultraviolet':1240/energy>780?'infrared':'visible'};\n}\nexport function energyY(n:number,Z:number,height:number){const floor=bohrEnergy(1,Z);return 12+(bohrEnergy(n,Z)/floor)*(Math.max(24,height)-24);}\nexport function spacedEnergyLabels(lower:number,upper:number,Z:number,height:number){\n const rows=[upper,lower].map(n=>({n,y:energyY(n,Z,height),labelY:energyY(n,Z,height)})).sort((a,b)=>a.y-b.y);\n const gap=Math.min(30,Math.max(18,(height-20)/2));rows[0].labelY=Math.max(12,Math.min(rows[0].y,height-gap-12));rows[1].labelY=Math.max(rows[0].labelY+gap,Math.min(rows[1].y,height-12));return rows;\n}\n", "docs/atomic-radiation-lesson.md": "# Atomic radiation lesson update\n\nApply `patch-atomic-radiation-lesson.sh` from the project root after the earlier atomic responsive patch. The installer checks source versions before changing anything, backs up originals and is safe to run twice. It changes only the atomic components, their hosts, lesson logic, tests and this note. No dependencies are added.\n\nRun `node checks/atomic-models-layout.cjs` and `npm run build`. Restart development or redeploy using your usual workflow. The shared component serves `/simulations/atomic-models` and `/embed/atomic-models`.\n\n## Teaching sequence\n\n- **Cycle** plays arrival, absorption/excitation, a slowed excited-state hold, relaxation/emission and return to the lower state.\n- **Send photon** stops at the excited state so the instructor can explain stored energy. **Relax** releases it as one outgoing photon.\n- **Step** advances a whole teaching stage; **Pause/Resume** controls continuous playback. **Reset** restores the initial lower state.\n- Select any pair of states from n=1 to n=7. The photon energy equals the selected gap in matching mode. Off-resonance mode chooses a photon between neighbouring transition energies, below ionisation, and demonstrates no bound-state absorption in the idealised model.\n- The photon travels in real space. The vertical arrow belongs only to the energy diagram: it is not an electron trajectory or radiation beam. There is no animated radial electron path through forbidden energies.\n- Excitation occurs only when the photon arrives. During emission, the atom's energy decreases when the outgoing photon is created.\n\nThis is a one-electron Bohr teaching model with schematic orbit radii, wave shape, directions and slowed timing. Actual n²/Z radii remain in the live numerical readout. Sublevel selection rules, fine structure, Zeeman splitting, cascades and realistic lifetimes are not simulated. Photon colours distinguish events; ultraviolet and infrared radiation are not visible to the eye. These are energy-level teaching examples, not an assertion that every microscopic absorption follows the same geometrical path.\n\nThomson is shown as a continuous positive pudding with eight embedded negative electron symbols, not a nucleus surrounded by orbiting electrons. Plus marks indicate the distributed positive medium; they are not separate protons. Small illustrative vibrations do not turn the embedded electrons into orbiting particles.\n\n## Classroom layout\n\nClassroom view is one viewport with compact essential controls at the top. The legacy long parameter section is hidden there; advanced parameter settings remain accessible in normal view. Desktop and landscape show the atom and energy diagram together. Portrait phones use Atom / Energy states switches so each diagram has usable space. Explanatory text is shortened in compact classroom view. The normal page can scroll as usual.\n\n## Validation\n\nAutomated checks cover photon-arrival causality, excitation hold, energy loss at emission, off-resonance rejection, hydrogen-like energy/wavelength calculations, selected-level label spacing, rendering of all four models and restarting the canvas when switching back from Bohr.\n\nA static QA harness built from the actual React lab and SimulationStage components was checked in a browser at desktop size and at 375×667 portrait and 844×390 landscape sizes. Settled classroom content fitted within those viewports. Absorption, held excitation, relaxation and model switching were exercised. This was component browser QA, not a deployment or exhaustive test on every device.\n\nPhysics references:\n- https://openstax.org/books/chemistry-2e/pages/6-2-the-bohr-model\n- https://openstax.org/books/university-physics-volume-3/pages/6-4-bohrs-model-of-the-hydrogen-atom\n- https://history.aip.org/exhibits/electron/jjelectr.htm\n"},expected={"src/components/simulation/AtomicModelsCanvas.tsx": "9836bdbe9449025974a843615d1e184b52472dd5535606d1ba77b5c15d476100", "src/components/simulation/atomic-models.css": "6f0e28abfe9080e1cfd74d2a26f46047d0d9bf25cd0a80bef7ba069598a9c448", "src/app/simulations/atomic-models/page.tsx": "417a34402adb6dcb1135c42795f648e339cbc3c0f50e54fa5fe667bf784128ce", "src/app/embed/atomic-models/page.tsx": "8760174894d39dff34f6a6721d2b269fbd21dac012bd006abbd7bdce20bc488a", "checks/atomic-models-layout.cjs": "a2bf44048b4ad560d707cb4b444ffecb387fe8bda973098fe549eedb3f1b9a7b", "src/components/simulation/BohrRadiationLab.tsx": null, "src/lib/physics/bohrLesson.ts": null, "docs/atomic-radiation-lesson.md": null};
const root=process.cwd(),normalize=s=>s.replace(/\r\n/g,'\n'),hash=s=>crypto.createHash('sha256').update(normalize(s)).digest('hex');
function stop(message){console.error('Stopped: '+message+' No source files changed.');process.exit(1);}
