for(const [file,content]of Object.entries(files)){const current=fs.existsSync(file)?fs.readFileSync(file,'utf8'):null;if(current!==null&&normalize(current)===normalize(content))continue;if(current===null?expected[file]!==null:expected[file]===null||hash(current)!==expected[file])conflicts.push(file);else changed.push(file);}
